    w=p[0]
    return p[1]+p[2]*P+p[3]*P**2+p[4]*np.sin(w*t)+p[5]*np.cos(w*t)+p[6]*P*np.sin(w*t)+p[7]*P*np.cos(w*t)+p[8]*t
best=None
