import numpy as np
lt=np.log(t); lP=np.log(P); sP=np.sqrt(P)
Tb={'1':np.ones_like(t),'t':t,'lt':lt,'1/t':1/t,'t2':t**2,'sin':np.sin(t)}
Pb={'1':np.ones_like(P),'sP':sP,'P':P,'PlP':P*lP,'P2':P**2,'lP':lP,'P1.5':P**1.5}
cols=[];names=[]
for a,va in Tb.items():
    for b,vb in Pb.items():
        cols.append(va*vb); names.append(a+'*'+b)
A=np.column_stack(cols)
c=np.linalg.lstsq(A,dP_dt,rcond=None)[0]
r=dP_dt-A@c
print('NMSE',np.mean(r**2)/np.var(dP_dt))
